    if (typeof window === 'undefined') {
        return {
            scrollX: augmentMotionValue(scrollX),
            scrollY: augmentMotionValue(scrollY),
            scrollXProgress: augmentMotionValue(scrollXProgress),
            scrollYProgress: augmentMotionValue(scrollYProgress)
        };
    }
